message.content:
{
  "html": "<div data-ui-unit="E4b" class="e4b-card">
  <div class="e4b-header">
    <div class="e4b-identity">
      <img class="e4b-avatar" src="assets/reference/avatar-2.png" alt="박민준 프로필 이미지">
      <div class="e4b-info">
        <div class="e4b-name">박민준</div>
        <div class="e4b-meta-row">
          <img class="e4b-badge-check" src="assets/reference/badge-check.svg" alt="인증">
          <span class="e4b-badge-label">인증</span>
          <span class="e4b-divider"></span>
          <span class="e4b-role">소프트웨어 개발</span>
        </div>
      </div>
    </div>
    <button class="e4b-action-btn" aria-pressed="false" disabled title="박민준 찜하지 않은 상태 예시">
      <img class="e4b-heart-icon" src="assets/reference/heart.svg" alt="찜">
    </button>
  </div>
</div>",
  "css": ".e4b-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  min-width: 0;
}

.e4b-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  width: 100%;
}

.e4b-identity {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
  flex: 1;
}

.e4b-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.e4b-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.e4b-name {
  font-size: 18px;
  line-height: 24px;
  font-weight: 700;
  color: var(--ink, #283548);
  white-space: nowrap;
}

.e4b-meta-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.e4b-badge-check {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

.e4b-badge-label {
  font-size: 14px;
  line-height: 20px;
  color: var(--purple, #713ac7);
  font-weight: 500;
}

.e4b-divider {
  width: 1px;
  height: 20px;
  background-color: #d1d5db;
  flex-shrink: 0;
}

.e4b-role {
  font-size: 14px;
  line-height: 20px;
  padding: 1px 6px;
  border-radius: 6px;
  background-color: #f3effc;
  color: var(--purple, #713ac7);
  white-space: nowrap;
}

.e4b-action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border: none;
  background: transparent;
  cursor: default;
  padding: 0;
  margin-left: 8px;
  flex-shrink: 0;
}

.e4b-heart-icon {
  width: 100%;
  height: 100%;
  display: block;
}"
}
